/**
 * @name User-controlled URL in HTTP requests
 * @description Detects flows from remote/user input into urllib3 request URLs, which may indicate SSRF or open redirect risks in applications using this library.
 * @kind path-problem
 * @problem.severity warning
 * @id py/urllib3/user-controlled-url
 * @tags security
 *       external/cwe/cwe-918
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module UrlConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(API::CallNode call |
      call = API::moduleImport("urllib3").getMember(["request", "PoolManager", "HTTPConnectionPool", "HTTPSConnectionPool"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module UrlFlow = TaintTracking::Global<UrlConfig>;
import UrlFlow::PathGraph

from UrlFlow::PathNode source, UrlFlow::PathNode sink
where UrlFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "User-controlled data flows into urllib3 request URL $@.", source.getNode(), "user input"
